import { TemplateView } from "./TemplateView";
import { IStatus } from './StatusManager';

export default class ReSpinStatus implements IStatus {
    data?: any;
    templateView: TemplateView
    setContext(context: TemplateView) {
        this.templateView = context;
        return this;
    }
    onEnter(data?: any) {
        this.templateView.setSpinFrameVisible(false);
        this.templateView.setBetFrameVisible(false);

    }
    onExit(data?: any) {

    }
}