import { _decorator, Component, Label, Node, tween, UIOpacity, Vec2, Vec3 } from 'cc';
import StoreManager from '../../store/StoreManager';
const { ccclass, property } = _decorator;

@ccclass('1003/ToastView')
export class ToastView extends Component {
    alertInfo: any
    @property(Label)
    messageLabel: Label = null
    override start() {

    }

    protected override onLoad(): void {
        this.alertInfo = this.getAlertInfo();
        this.messageLabel.string = this.alertInfo.message;
        const uiOpacity = this.node.getComponent(UIOpacity);
        console.log('uiOpacity = ', uiOpacity);
        tween(this.node)
            .to(0.5, { position: new Vec3(this.node.position.x, 50, 0) })
            .start();

        tween(uiOpacity)
            .delay(0.3)
            .to(0.5, { opacity: 0 })
            .call(() => {
                this.node.destroy(); // ← 直接刪除
            })
            .start();
    }

    getAlertInfo() {
        const viewStore = StoreManager.getInstance().getViewStore();
        return viewStore.alertInfo;
    }
}

