// 贏分演出等級門檻
export const WinTier = {
    WIN: 'win',
    BIG: 'big',
    MEGA: 'mega',
    SUPER: 'super',
    EPIC: 'epic',
    TOTAL: 'total',
} as const;
export type WinTier = (typeof WinTier)[keyof typeof WinTier];

// WinTier 由小到大排序 WIN/TOTAL
const WIN_TIER_ORDER: WinTier[] = [WinTier.BIG, WinTier.MEGA, WinTier.SUPER, WinTier.EPIC];

/**
 * 判斷贏分等級有沒有達到門檻。
 *
 * @param tier 這次的贏分等級；null 代表沒達到任何等級。
 * @param minTier 要求的最低等級；null 代表沒有設門檻。
 * @returns 達到門檻時為 true；任一為 null 或不在 {@link WIN_TIER_ORDER} 裡時為 false。
 */
export function matchMinWinTier(tier: WinTier | null, minTier: WinTier | null): boolean {
    if (!tier || !minTier) return false;
    const tierIdx = WIN_TIER_ORDER.indexOf(tier);
    const minIdx = WIN_TIER_ORDER.indexOf(minTier);
    if (tierIdx < 0 || minIdx < 0) return false;
    return tierIdx >= minIdx;
}

/**
 * 免費遊戲加局（GDD 4.3）時 FGCounter 的「放大後彈回」演出參數，餵給 `AppAnimation.playBounce()`。
 * 數值單純是手感，實機覺得太誇張或太小就改這裡。
 */
export const FG_RETRIGGER_BOUNCE = { scaleMultiplier: 1.6, durationUp: 0.18, durationDown: 0.22 } as const;

/**
 * 加局演出的總長度（秒）。`PlayFreeRoundTask` 用它等演出播完才接下一局，
 * 刻意由上面那組參數算出來——改動效時長不用記得同步改等待時間，兩邊不會走鐘。
 */
export const FG_RETRIGGER_BOUNCE_DURATION = FG_RETRIGGER_BOUNCE.durationUp + FG_RETRIGGER_BOUNCE.durationDown;

/**
 * 加局演出播完之後的停頓（秒），停完才接下一局。
 *
 * 加局是**本局盤面**再湊滿 Scatter 的結果，所以排在本局演出的最後；而扣局是跟著下一局的轉輪
 * 一起發生的（見 `PlayFreeRoundTask.run()` 開頭），兩者天然分開在不同時間點，不會併成一個淨值。
 */
export const FG_RETRIGGER_HOLD = 0.35;
