import { Logger } from '../utils/Logger';
/**
 * GameTask
 *
 * 仿 SGEngine 的任務佇列模式：把一段演出／流程包裝成一顆 Task，
 * 由 GameTaskQueue 依序（或平行）消費，取代目前 GameContext 內大量手寫
 * `async/await` + `Promise` 串接的寫法。
 *
 * 生命週期（模板方法）：
 *   execute() → onStart()（子類實作實際邏輯）
 *   子類完成時呼叫 finish() → onFinish()（可覆寫，預設 no-op）→ onEnd()（可覆寫，預設 no-op）→ 觸發 taskFinish callback
 *
 * 設計原則：
 * - 不依賴 MobX／RxJS，純 TS class + callback。
 * - 一個 Task 只能 finish 一次（idempotent），避免重複觸發下一顆任務。
 * - 子類別只需要覆寫 onStart()，並在非同步流程完成時呼叫 this.finish()。
 */
export abstract class GameTask {
    private _isFinished = false;
    private _onFinishedCallback: (() => void) | null = null;

    /** Task 是否已完成 */
    public get isFinished(): boolean {
        return this._isFinished;
    }

    /**
     * 由 GameTaskQueue／GameTaskSequence／GameTaskParallel 呼叫，啟動這顆 Task。
     * 不要覆寫這個方法，邏輯請寫在 onStart()。
     */
    public execute(onFinished: () => void): void {
        this._isFinished = false;
        this._onFinishedCallback = onFinished;
        this.onStart();
    }

    /** 子類別實作實際邏輯的地方；非同步完成時務必呼叫 this.finish() */
    protected abstract onStart(): void;

    /** 子類別完成時呼叫；idempotent，重複呼叫不會有副作用 */
    protected finish(): void {
        if (this._isFinished) return;
        this._isFinished = true;

        this.onFinish();
        this.onEnd();

        const callback = this._onFinishedCallback;
        this._onFinishedCallback = null;
        callback?.();
    }

    /** 完成當下的第一個掛勾（可覆寫），預設 no-op */
    protected onFinish(): void {
        // no-op，供子類覆寫
    }

    /** 完成的最後掛勾（可覆寫），預設 no-op，通常用來釋放資源 */
    protected onEnd(): void {
        // no-op，供子類覆寫
    }
}

/**
 * 將一個同步／立即完成的函式包裝成 Task。
 * 對應 SGEngine 裡「純資料處理、不需要等待演出」的 Task（例如更新倍數 UI）。
 */
export class GameTaskFn extends GameTask {
    constructor(private readonly fn: () => void) {
        super();
    }

    protected onStart(): void {
        this.fn();
        this.finish();
    }
}

/**
 * 將一個回傳 Promise 的函式包裝成 Task。
 * 對應 SGEngine 裡呼叫 SlotMachine.doXxx(..., finishCallback) 的模式，
 * 讓既有的 async 演出函式可以直接塞進 Task 佇列。
 */
export class GameTaskPromise extends GameTask {
    constructor(private readonly fn: () => Promise<void>) {
        super();
    }

    protected onStart(): void {
        this.fn()
            .catch((error) => {
                console.warn('[GameTaskPromise] task failed', Logger.fmt(error));
            })
            .finally(() => {
                this.finish();
            });
    }
}
