import { DEFAULT_PRESENTATION_CONFIG, type PresentationConfig } from './PresentationConfig';
import type { WinTier } from './GameConst';

// DebugPanel 執行期間使用 不寫進共用 SlotGameStore
export default class PresentationStore {
    private static instance: PresentationStore;
    /**
     * @returns 全域唯一的 PresentationStore；第一次呼叫時建立。
     */
    static getInstance(): PresentationStore {
        if (!PresentationStore.instance) {
            PresentationStore.instance = new PresentationStore();
        }
        return PresentationStore.instance;
    }

    private _config: PresentationConfig = DEFAULT_PRESENTATION_CONFIG;
    get config(): PresentationConfig {
        return this._config;
    }
    /** 初始化 */
    setConfig(config: PresentationConfig): void {
        this._config = config;
    }
    /** DebugPanel 專用 */
    setFeatureRoundWinPresentationEnabled(enabled: boolean): void {
        this._config = { ...this._config, featureRoundWinPresentationEnabled: enabled };
    }
    /**
     * 設定免費局單局贏分要達到哪一階才播報獎。
     *
     * @param minTier 門檻等級。
     */
    setFeatureRoundWinPresentationMinTier(minTier: WinTier): void {
        this._config = { ...this._config, featureRoundWinPresentationMinTier: minTier };
    }
}
