import { _decorator, Color, Component, Label, Node, sp, Sprite, tween, Tween, UIOpacity, UITransform } from 'cc';
import { SlotMachineModel } from '../model/SlotMachineModel';
import { ReelView_1003 } from './ReelView_1003';
import type { AchieveItem } from '../../types/SpinTypes';

const { ccclass, property } = _decorator;

@ccclass('1003/SlotMachineView')
export class SlotMachineView extends Component {
    @property([ReelView_1003])
    reelViews: ReelView_1003[] = [];

    public model: SlotMachineModel = null!;

    /**
     * 綁定模型、把各欄平均排開，並逐一初始化轉輪。
     *
     * @param model 這台機台的模型，每一欄對應一個 reelModel。
     */
    init(model: SlotMachineModel): void {
        this.model = model;
        this.layoutReelColumns();

        for (let i = 0; i < this.reelViews.length; i++) {
            this.reelViews[i].init(model.reelModels[i]);
            this.reelViews[i].node.setSiblingIndex(i);
        }
    }

    // 依寬度平均分佈 reelViews
    /** 依自己的寬度把各欄平均分佈，不用手動擺位置。 */
    private layoutReelColumns(): void {
        const count = this.reelViews.length;
        if (count === 0) return;
        const width = this.getComponent(UITransform)?.contentSize.width ?? 0;
        if (width <= 0) return;
        const colWidth = width / count;
        for (let i = 0; i < count; i++) {
            const x = -width / 2 + colWidth * (i + 0.5);
            const reelNode = this.reelViews[i].node;
            reelNode.setPosition(x, reelNode.position.y, reelNode.position.z);
        }
    }

    /**
     * 整組套用轉輪節奏。
     *
     * @param bd 起轉時長（秒）。
     * @param lt 循環時長（秒）。
     * @param ed 停輪時長（秒）。
     */
    applySpeed(bd: number, lt: number, ed: number): void {
        for (const reel of this.reelViews) {
            reel.applySpeed(bd, lt, ed);
        }
    }

    /** 目前的轉輪節奏設定，讀第一顆轉輪的值（applySpeed 一律整組套用，理論上彼此一致） */
    getSpeed(): { beginDuration: number; loopTime: number; endDuration: number } | null {
        return this.reelViews[0]?.getSpeed() ?? null;
    }

    /**
     * 整組套用起轉與停輪的緩動曲線。
     *
     * @param beginEase 起轉曲線名稱。
     * @param endEase 停輪曲線名稱。
     */
    applyEase(beginEase: string, endEase: string): void {
        for (const reel of this.reelViews) {
            reel.applyEase(beginEase, endEase);
        }
    }

    /** 目前的開始/結束緩動名稱，讀第一顆轉輪的值（applyEase 一律整組套用，理論上彼此一致） */
    getEase(): { beginEase: string; endEase: string } | null {
        return this.reelViews[0]?.getEase() ?? null;
    }

    /**
     * 取某一格的符號節點。
     *
     * @param col 欄索引。
     * @param row 可見列（0 起算，由上往下）。
     * @returns 符號節點；座標超出範圍時回 null。
     */
    getSymbolAt(col: number, row: number): Node | null {
        return this.reelViews[col]?.getVisibleSymbol(row) ?? null;
    }

    private static readonly SPINE_ANIM_MAP: Record<string, string> = {
        fu: 'idle',
        caishen: 'animation',
        jin_chan: 'h2',
        wealth_tree: 'h3',
        golden_carp: 'h4',
        golden_ruyi: 'h5',
        a: 'n1',
        k: 'n2',
        q: 'n3',
        j: 'n4',
        ten: 'n5',
    };

    /**
     * 播中獎符號的動畫，同時把沒中獎的格子壓暗。
     *
     * @param achieves 中獎資料，含每組的座標。
     * @param loop 動畫是否循環，預設 true。
     * @returns 全部開始播放後 resolve；loop 為 false 時等播完。
     */
    playSymbolWins(achieves: AchieveItem[], loop: boolean = true): Promise<void> {
        return new Promise<void>((resolve) => {
            this.setSymbolSpinesTimeScale(1);
            const toPlay: { col: number; row: number; animName: string }[] = [];
            for (const achieve of achieves) {
                if (achieve.type !== 'line' || !achieve.line || !achieve.icon) continue;
                const animName = SlotMachineView.SPINE_ANIM_MAP[achieve.icon];
                if (!animName) continue;
                const lineStr = String(achieve.line).replace(/,/g, '');
                const rows = lineStr.split('').map(Number);
                const len = achieve.length ?? rows.length;
                const isLeft = achieve.left === 1;
                for (let i = 0; i < len; i++) {
                    const col = isLeft ? i : 4 - i;
                    toPlay.push({ col, row: rows[i], animName });
                }
            }
            if (toPlay.length === 0) {
                resolve();
                return;
            }

            // 壓黑非中獎圖示
            this.dimNonWinning(toPlay);

            if (loop) {
                // loop=true（輪播每條線）：等第一個 spine 播完一輪即繼續
                let resolved = false;
                const onFirst = () => {
                    if (!resolved) {
                        resolved = true;
                        resolve();
                    }
                };
                let hasBound = false;
                for (const { col, row, animName } of toPlay) {
                    const cb = hasBound ? undefined : onFirst;
                    const played = this.reelViews[col]?.playWinAnim(row, animName, true, cb);
                    if (!hasBound && played) hasBound = true;
                }
                if (!hasBound) resolve();
            } else {
                // loop=false（全部一起播一次）：Cocos Creator setCompleteListener 對 loop=false 不觸發
                // 改用 timeout：動畫 1 秒 + 200ms buffer
                let hasAny = false;
                for (const { col, row, animName } of toPlay) {
                    const played = this.reelViews[col]?.playWinAnim(row, animName, false);
                    if (played) hasAny = true;
                }
                if (!hasAny) {
                    resolve();
                    return;
                }
                this.scheduleOnce(resolve, 1);
            }
        });
    }

    /** 停掉所有中獎動畫並把壓暗的格子還原。 */
    stopAllSymbolWins(): void {
        for (const reel of this.reelViews) {
            reel.stopAllWinAnims();
        }
        this.restoreAllOpacity();
    }

    /**
     * 整台調整符號 spine 的播放速度。
     *
     * @param scale 倍率，1 為原速。
     */
    setSymbolSpinesTimeScale(scale: number): void {
        for (const reel of this.reelViews) {
            for (const sk of reel.symbolSpines) {
                if (sk) sk.timeScale = scale;
            }
        }
    }

    private static readonly DIM_OPACITY = 80;

    private static readonly DIM_DURATION = 0.25;
    private static readonly DIM_COLOR = new Color(80, 80, 80, 255);
    private static readonly FULL_COLOR = new Color(255, 255, 255, 255);

    /**
     * 把不在中獎位置的符號壓暗，凸顯中獎組合。
     *
     * @param winPositions 中獎格子的座標。
     */
    private dimNonWinning(winPositions: { col: number; row: number }[]): void {
        const winSet = new Set(winPositions.map((p) => `${p.col}_${p.row}`));
        for (let col = 0; col < this.reelViews.length; col++) {
            for (let row = 0; row < this.reelViews[col].visibleRowCount; row++) {
                const symbol = this.reelViews[col].getVisibleSymbol(row);
                if (!symbol) continue;
                const target = winSet.has(`${col}_${row}`) ? SlotMachineView.FULL_COLOR : SlotMachineView.DIM_COLOR;
                this.tweenSymbolColor(symbol, target);
            }
        }
    }

    /** 把所有被壓暗的符號還原成正常顏色。 */
    private restoreAllOpacity(): void {
        for (let col = 0; col < this.reelViews.length; col++) {
            for (let row = 0; row < this.reelViews[col].visibleRowCount; row++) {
                const symbol = this.reelViews[col].getVisibleSymbol(row);
                if (!symbol) continue;
                this.tweenSymbolColor(symbol, SlotMachineView.FULL_COLOR);
            }
        }
    }

    /**
     * 用補間把符號顏色帶到目標值。
     *
     * @param symbol 符號節點。
     * @param target 目標顏色。
     */
    private tweenSymbolColor(symbol: Node, target: Color): void {
        for (const sprite of symbol.getComponentsInChildren(Sprite)) {
            Tween.stopAllByTarget(sprite);
            tween(sprite).to(SlotMachineView.DIM_DURATION, { color: target }).start();
        }
        for (const skeleton of symbol.getComponentsInChildren(sp.Skeleton)) {
            Tween.stopAllByTarget(skeleton);
            tween(skeleton).to(SlotMachineView.DIM_DURATION, { color: target }).start();
        }
        for (const label of symbol.getComponentsInChildren(Label)) {
            Tween.stopAllByTarget(label);
            tween(label).to(SlotMachineView.DIM_DURATION, { color: target }).start();
        }
    }

    /**
     * 依名稱矩陣重建各欄的輪帶內容。
     *
     * @param iconMatrix 外層是欄、內層是該欄的符號名稱。
     */
    updateStrips(iconMatrix: string[][]): void {
        for (let i = 0; i < this.reelViews.length; i++) {
            if (iconMatrix[i]) {
                this.reelViews[i].updateStrip(iconMatrix[i]);
            }
        }
    }
}
