import type { SlotGridLayout } from '../models/SlotGrid';

export interface SlotLayoutSource {
    readonly cols: number;
    /** 每欄可視列數一致時給單一數字；不規則輪帶（如葫蘆型盤面）給各欄列數的陣列。 */
    readonly rows: number | readonly number[];
}

export const TEMPORARY_SLOT_LAYOUT_SOURCE: SlotLayoutSource = { cols: 6, rows: 5 };

/**
 * 各遊戲的本地盤面形狀。只有「不規則輪帶」的遊戲需要登記——沒登記的一律沿用
 * TEMPORARY_SLOT_LAYOUT_SOURCE，行為與登記表存在之前完全相同。
 *
 * 這份表存在的理由：後端的 gameInfo 只會回扁平的 { cols, rows }，表達不出逐欄列數，
 * 前端沒有其他管道知道自己是葫蘆型盤面。
 */
const SLOT_LAYOUT_BY_GAME: Readonly<Record<string, SlotLayoutSource>> = {
    // 巨亨麻將：4-5-5-5-4 葫蘆型
    '1003': { cols: 5, rows: [4, 5, 5, 5, 4] },
};

/** 取得該遊戲的本地登記形狀；未登記回傳共用預設值。 */
export function getSlotLayoutSource(gameId: string): SlotLayoutSource {
    return SLOT_LAYOUT_BY_GAME[gameId] ?? TEMPORARY_SLOT_LAYOUT_SOURCE;
}

/**
 * 收到後端 gameInfo 時決定最終形狀。
 *
 * 後端只會給單一 rows，直接採用會把本地登記的逐欄陣列壓成矩形，因此對有登記的遊戲
 * 以本地形狀為準。欄數對不上時例外——那代表後端換過盤面規格，繼續套用舊陣列只會讓
 * SlotGridDecoder 丟 RangeError 整場 spin 解不開，寧可退回後端值先讓畫面是矩形。
 */
export function mergeServerLayoutSource(gameId: string, server: SlotLayoutSource): SlotLayoutSource {
    const configured = getSlotLayoutSource(gameId);
    if (typeof configured.rows === 'number') return server;

    if (server.cols !== configured.cols) {
        console.warn(`[GridLayoutConfig] ${gameId} 本地登記 ${configured.cols} 欄，後端回 ${server.cols} 欄，改用後端值`);
        return server;
    }

    return configured;
}

export function createSlotGridLayout(source: SlotLayoutSource): SlotGridLayout {
    const rows = source.rows;
    const isPerColumn = typeof rows !== 'number';
    return {
        columns: source.cols,
        // 不規則輪帶取各欄最大值當 visibleRows，讓 bufferRows 與後端的統一總列數仍然對得起來
        visibleRows: isPerColumn ? Math.max(...rows) : rows,
        visibleRowsPerColumn: isPerColumn ? rows : undefined,
        bufferRows: 0,
        bufferPlacement: 'start',
        sourceRowOrder: 'top-down',
        presentationRowOrder: 'top-down',
    };
}

/**
 * 以「實際收到的盤面」校正設定值。這是唯一每次都看得到真實維度的地方——
 * mergeServerLayoutSource 掛在 gameInfo 上，但非 mock 模式不會發 gameInfo
 * （見 HttpClientStore.fetchInitialGameData），設定值可能從頭到尾沒被伺服器修正過。
 *
 * 維度對不上時，本地登記的形狀（含不規則輪帶）一律讓位給實際資料：硬套下去只會讓
 * SlotGridDecoder.validate 丟 RangeError，整場 spin 解不開，畫面完全不動且無聲。
 */
export function resolveSlotGridLayout(grid: { Cols: number; Rows: number }, configured: SlotGridLayout): SlotGridLayout {
    // Rows 少於 visibleRows 是同一類問題：bufferRows 會被夾成 0，
    // 接著 decoder 的 `source.rows !== visibleRows + bufferRows` 一樣會丟例外
    if (grid.Cols !== configured.columns || grid.Rows < configured.visibleRows) {
        console.warn(`[GridLayoutConfig] 盤面維度與設定不符（實際 ${grid.Cols}x${grid.Rows}，設定 ${configured.columns}x${configured.visibleRows}），改用實際維度`);
        return {
            ...configured,
            columns: grid.Cols,
            visibleRows: grid.Rows,
            visibleRowsPerColumn: undefined,
            bufferRows: 0,
        };
    }

    return {
        ...configured,
        bufferRows: Math.max(0, grid.Rows - configured.visibleRows),
    };
}
