import { _decorator, Node, profiler, instantiate, Component, assetManager, UITransform, Prefab, screen, Canvas, director, view, sys } from 'cc';
import StoreManager from './store/StoreManager';
import { initI18n } from './i18n/i18nHelper';
import { GAMEVIEWMAP, VIEWMAP, VIEWLEVEL } from './store/StoreMap';
import AppAssetBundle from './utils/AppAssetBundle';
import AppViewPool from './ui/AppViewPool';
import EagleTracker from './tracking/EagleTracker';
import TrackerMap from './tracking/TrackerMap';
import GameConfigManager from './config/GameConfigManager';
import { isMock } from './config/GameConfig';
import { NativeBundleUpdateView } from './hotupdate/NativeBundleUpdateView';
import { startGameMock } from './net/mocks/start';
import { GAME_EVENT_TYPE, gameRuntimeEventBus } from './events/GameRuntimeEventBus';
import AppConfig from './config/AppConfig';
import { EventComponent } from './events/EventComponent';
import type { TypedEventBus } from './events/TypedEventBus';
import { PopupManager } from './ui/PopupView/PopupStack';
const { ccclass, property } = _decorator;
@ccclass('1003/GameRoot')
export class GameRoot extends EventComponent {
    /** EventComponent.subscribeEvent 是 protected，這裡轉一層 public 供本類別的事件訂閱與外部呼叫 */
    public subscribeGameEvent<TEvents extends object, K extends keyof TEvents>(
        bus: TypedEventBus<TEvents>,
        type: K,
        handler: (payload: TEvents[K]) => void
    ): void {
        this.subscribeEvent(bus, type, handler);
    }

    @property(Node)
    staticNode: Node;

    @property(Node)
    gameNode: Node;

    @property(Node)
    templateNode: Node;

    @property(Node)
    middleNode: Node;

    @property(Node)
    topNode: Node;

    @property(Node)
    loadingView: Node;

    private static readonly TOP_LAYER = 4;

    protected override onLoad(): void {
        console.log('GameRoot onLoad');
        this.trackLayer(this.topNode, GameRoot.TOP_LAYER);
        PopupManager.setLayer(this.topNode);
    }
    protected override start() {
        console.log('GameRoot onStart');
        // 關閉 FPS 顯示
        if (!AppConfig.DEBUG) profiler.hideStats();
        // profiler.showStats();
        this.initViewPool();
        this.registerStore();
        this.registerReactions();
        void this.initial();
    }

    private trackLayer(root: Node, layer: number): void {
        const apply = (n: Node) => {
            n.layer = layer;
            n.on(Node.EventType.CHILD_ADDED, (child: Node) => {
                this.setLayerRecursive(child, layer);
                apply(child);
            });
            for (const c of n.children) apply(c);
        };
        apply(root);
    }

    private setLayerRecursive(node: Node, layer: number): void {
        node.layer = layer;
        for (const c of node.children) this.setLayerRecursive(c, layer);
    }

    addGameNode(view) {
        if (!this.gameNode) {
            console.warn('[GameRoot] gameNode null, skip addGameNode');
            return;
        }
        this.gameNode.addChild(view);
    }

    addTemplateNode(view) {
        if (!this.templateNode) {
            console.warn('[GameRoot] templateNode null, skip addTemplateNode');
            return;
        }
        this.templateNode.addChild(view);
    }

    addMiddleNode(view) {
        if (!this.middleNode) {
            console.warn('[GameRoot] middleNode null, skip addMiddleNode');
            return;
        }
        this.middleNode.addChild(view);
    }

    addTopNode(view) {
        if (!this.topNode) {
            console.warn('[GameRoot] topNode null, skip addTopNode');
            return;
        }
        this.topNode.addChild(view);
    }

    deleteView(viewName) {
        const containers = [this.node, this.gameNode, this.templateNode, this.middleNode, this.topNode];

        let found = false;
        for (const container of containers) {
            for (let i = container.children.length - 1; i >= 0; i--) {
                if (container.children[i].name === viewName) {
                    container.children[i].destroy();
                    found = true;
                }
            }
        }
        if (!found) console.warn(`[removeView] 找不到節點: ${viewName}`);
    }
    storeManager: StoreManager;
    viewStore: any;
    viewPool: AppViewPool;
    deviceStore: any;
    templateView: Node;
    templateViewH: Node;
    bundlePath: string;
    initViewPool() {
        this.viewPool = AppViewPool.getInstance();
    }
    async initial() {
        const startTime = performance.now();
        EagleTracker.trackerEvent(TrackerMap.GAME_LOAD_START);
        if (isMock()) await startGameMock();
        console.log('------ [GameRoot] initial ------ ');

        // 原生熱更新由本 bundle 自己的 LoadingView 負責，Web／Editor Preview 完全略過（比照 1002 GameRoot）
        if (sys.isNative) {
            const updateView = this.node.getComponentInChildren(NativeBundleUpdateView);
            if (updateView) await updateView.ensureUpdated();
            else console.warn('[GameRoot] 未掛 NativeBundleUpdateView，略過 1003 原生熱更新');
        }

        // 3.初始化 i18n
        console.log('------ [GameRoot] initial initI18n ------ ');
        await initI18n();
        console.log('------ [GameRoot] loadServerConfig ------ ');
        //載入 config 檔案
        await this.loadServerConfig();
        // 2.載入Bundle
        console.log('------ [GameRoot] loadBundle ------ ');
        await this.loadBundle();
        // 4.初始化 TemplateView
        console.log('------ [GameRoot] initial addTemplateView ------ ');
        await this.addTemplateView();
        // 5.連線遊戲伺服器，取得遊戲初始資料
        console.log('------ [GameRoot] initial addGamePrefab ------ ');
        await this.addGamePrefab();
        console.log('------ [GameRoot] initial connectGameServer ------ ');
        await this.connectGameServer();
        // 6.移除 LoadingView
        this.removeLoadingView();
        // this.removeLoadingView();
        this.deviceStore.checkOrientation();
        console.log('------ LOADING TIME ------ ');
        console.log('Total load time: ', performance.now() - startTime);
        // entry 的 SubGame.ts 在按下進場那一刻寫進 globalThis 的時間戳 沒有這個 key 就不印
        const enterStartTime = (globalThis as Record<string, unknown>).__subGameEnterStartTime__;
        if (typeof enterStartTime === 'number') {
            console.log('[GameRoot] 熱更新下載開始 到 遊戲出現 總耗時: ', Date.now() - enterStartTime, 'ms');
        }
        EagleTracker.trackerEvent(TrackerMap.GAME_LOAD_COMPLETE, { total_load_time_ms: performance.now() - startTime });
    }
    registerStore() {
        this.storeManager = StoreManager.getInstance();
        this.viewStore = this.storeManager.getViewStore();
        this.deviceStore = this.storeManager.getDeviceStore();
    }

    registerReactions() {
        // mobx 移除計劃：ViewStore/DeviceStore 欄位已改由 gameRuntimeEventBus 通知，不再用 mobx reaction
        this.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.VIEW_NAME_CHANGED, (e) => this.addView(e.viewName));

        this.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.GAME_VIEW_NAME_CHANGED, (e) => this.addVGameView(e.gameViewName));

        this.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.DELETE_VIEW_NAME_CHANGED, (e) => this.handleDeleteView(e.deleteViewName));
        // 原本 fireImmediately: false，這裡不用手動呼叫一次

        this.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.DEVICE_ORIENTATION_CHANGED, (e) => this.orientation(e.orientation));
        // 原本 fireImmediately: false，這裡不用手動呼叫一次
    }

    orientation(orientation) {
        console.log('orientation = ', orientation);
        if (!this.templateView || !this.templateViewH) return;
        if (orientation == 'portrait') {
            this.templateView.x = 9999;
            this.templateViewH.x = 0;
            return;
        }
        this.templateView.x = 0;
        this.templateViewH.x = 9999;
    }
    async loadBundle() {
        let assetBundle = AppAssetBundle.getInstance(GameConfigManager.GAMEID);
        assetBundle.setImageRootPath('resources/Images/UI/');
        AppAssetBundle.getInstance(GameConfigManager.GAMEID);
        await assetBundle.preloadPrefabs(
            [VIEWMAP.TEMPLATEVIEWH.path, GAMEVIEWMAP.GAMEPREFAB.path],
            this.progressCallback.bind(this)
        );
        await assetBundle.preloadImages();
    }
    async connectGameServer() {
        console.log('------ [GameRoot] connectGameServer ------ ');
        console.log('------ gameInitial ------');
        await this.storeManager.getHttpClientStore().gameInitial();
        console.log('------ gameConfig ------');
        await this.storeManager.getHttpClientStore()?.gameConfig();
        console.log('------ Server  complete ------');
    }
    async addView(viewName) {
        await this.addViewToLayer(viewName, false);
    }
    async addVGameView(viewName) {
        await this.addViewToLayer(viewName, true);
    }

    async addViewToLayer(viewName, useGameViewPool) {
        if (!viewName) return;
        // 自動找出對應的 bundle
        const coreBundle = AppAssetBundle.getInstance(GameConfigManager.GAMEID);
        const bundleName = useGameViewPool ? GameConfigManager.GAMEID : ((await coreBundle.getInfoWithPath(viewName.path)) ?? GameConfigManager.GAMEID);
        const view = await this.viewPool.getView(viewName.path, bundleName);
        switch (viewName.level) {
            case VIEWLEVEL.GAME:
                this.addGameNode(view);
                break;
            case VIEWLEVEL.TEMPLATE:
                this.addTemplateNode(view);
                break;
            case VIEWLEVEL.MIDDLE:
                this.addMiddleNode(view);
                break;
            case VIEWLEVEL.TOP:
                this.addTopNode(view);
                break;
            default:
                return;
        }
    }
    /**
     * 收到「要刪哪個 view」的事件後移除節點並清掉事件值。
     *
     * 與底下真正做移除的 deleteView() 分開命名（合併前分屬 GameSceneViewModel 與 GameScene，
     * 同名會變成自我遞迴）；比照 1001 GameRoot 的 handleDeleteView。
     *
     * @param viewName 要移除的節點名稱。
     */
    handleDeleteView(viewName) {
        if (!viewName) return;
        this.deleteView(viewName);
        this.viewStore.setDeleteViewName('');
    }
    progressCallback(completedCount: number, totalCount: number, _item: any) {
        // console.log('completedCount = ', completedCount + 'totalCount = ' + totalCount);
        // console.log('completedCount = ', item);
        let progress = completedCount / totalCount;
        if (this.storeManager.getModel('LoadingStore')?.progress > progress) return;
        this.storeManager.getModel('LoadingStore')?.setProgress(progress);
    }
    /**
     * 建立橫版與直版的 TemplateView。
     *
     * entry 的版本會依 GAMES_WITH_OWN_TEMPLATE_VIEW 決定要載自己的還是共用的 Core 版本；
     * 這個 bundle 是獨立子遊戲，沒有 Core bundle，兩支一定是自己的，所以分支整段移除。
     */
    async addTemplateView() {
        const bundleId = GameConfigManager.GAMEID;

        this.templateView = instantiate(await AppAssetBundle.getInstance(bundleId).loadPrefab('resources/prefabs/TemplateViewH'));
        this.templateView.x = 9999;
        this.addTemplateNode(this.templateView);
        // 橫版是負責扣局數的 TemplateView.isPrimary
        this.isTemplateViewPrimary(this.templateView);

        this.templateViewH = instantiate(await AppAssetBundle.getInstance(bundleId).loadPrefab('resources/prefabs/TemplateViewV'));
        this.templateViewH.x = 9999;
        this.addTemplateNode(this.templateViewH);
        const isPortrait = this.deviceStore.isPortrait;
        if (isPortrait) {
            this.templateViewH.x = 0;
            return;
        }
        this.templateView.x = 0;
    }

    /**
     * 負責扣 AutoSpin 局數的TemplateView
     * 1002 是完全獨立的一份
     */
    private isTemplateViewPrimary(node: Node): void {
        const comp = node.getComponents(Component).find((c) => 'isPrimary' in c) as { isPrimary: boolean } | undefined;
        if (comp) comp.isPrimary = true;
        else console.warn('[GameRoot] isTemplateViewPrimary: 找不到帶 isPrimary 欄位的 TemplateView 元件');
    }

    async addGamePrefab() {
        //先寫死，之後會改成從其他地方讀取  bundle Name
        let gamePrefab = instantiate(await AppAssetBundle.getInstance(GameConfigManager.GAMEID).loadPrefab(GAMEVIEWMAP.GAMEPREFAB.path));
        this.addGameNode(gamePrefab);
    }
    async loadServerConfig() {
        console.log('------ [GameRoot] loadServerConfig ------ ');
        let gameConfigManager = GameConfigManager.getInstance();
        await gameConfigManager.updateServerConfig();
    }

    removeLoadingView() {
        this.loadingView.destroy();
    }
}
