import { sys } from 'cc';
import type { SlotApiSpinResponse } from '../net/SlotApiTypes';
import type { AccountCredentials, StoredAccount } from '../net/AccountApiTypes';
import type { BetHistoryDetail } from '../models/BetHistory';
import { GetBetDetailResponseHandler, GetBetHistoryResponseHandler, GetGameInfoResponseHandler, GetGameStateResponseHandler, JackpotPoolResponseHandler, SlotSpinResponseHandler } from '../net/SlotApiHandlers';
import { SLOT_API_RESPONSE_TYPE } from '../net/SlotApiTypes';
import { SlotApiClient } from '../net/SlotApiClient';
import { autoFallbackToMock, GameConfig, isMock } from '../config/GameConfig';
import { Logger } from '../utils/Logger';
import { startGameMock } from '../net/mocks/start';
import { GAMESTOREMAP } from './StoreMap';
import GameConfigManager from '../config/GameConfigManager';

const DEFAULT_SLOT_API_CONNECTION = {
    httpBaseUrl: 'https://slot-ws.ggap.elitepro.ltd',
    wsUrl: 'wss://slot-ws.ggap.elitepro.ltd/ws',
} as const;

/** 延遲讀取，避免 import 當下 GameConfig.config 還沒 fetch 完就讀到預設值 */
function getSlotApiConnection(): { httpBaseUrl: string; wsUrl: string } {
    return {
        httpBaseUrl: GameConfig.config?.gameHttpBaseUrl ?? DEFAULT_SLOT_API_CONNECTION.httpBaseUrl,
        wsUrl: GameConfig.config?.gameWsUrl ?? DEFAULT_SLOT_API_CONNECTION.wsUrl,
    };
}
const ACCOUNT_STORAGE_KEY = 'slot_api_account';
const TEST_ACCOUNT_PASSWORD = '123456789';
const INITIAL_DEPOSIT_AMOUNT = '10000';

export default class HttpClientStore {
    /** registry 用的 model 識別字串，對應原本 mobx-keystone @model('store/HttpClientStore') */
    public readonly $modelType = 'store/HttpClientStore';

    private _API_URL = '';
    get API_URL(): string {
        return this._API_URL;
    }
    setAPI_URL(value: string): void {
        this._API_URL = value;
    }

    private _userID = '';
    get userID(): string {
        return this._userID;
    }
    setUserID(value: string): void {
        this._userID = value;
    }

    private _signature = '';
    get signature(): string {
        return this._signature;
    }
    setSignature(value: string): void {
        this._signature = value;
    }

    private _authKey = '';
    get authKey(): string {
        return this._authKey;
    }
    setAuthKey(value: string): void {
        this._authKey = value;
    }

    private _isUpdate = true;
    get isUpdate(): boolean {
        return this._isUpdate;
    }
    setIsUpdate(value: boolean): void {
        this._isUpdate = value;
    }

    storeManager: any;
    debugControl: object | null = null;
    serviceURL: string | null = null;
    cashierURL: string | null = null;
    lobbyURL: string | null = null;
    private data: any = null;
    private currency: string = 'TWD';
    private mockMode: boolean = isMock();

    private mockTriggered = false;
    private readonly cache = {
        betDetails: new Map<string, BetHistoryDetail>(),
    };
    private slotApiClient: SlotApiClient | null = null;
    private slotApiLoginPromise: Promise<void> | null = null;

    /** 保留建構子參數是為了相容 GameConfigManager 裡 `new HttpClientStore({})` 的舊呼叫方式 */
    constructor(_props?: unknown) {}

    setManager(manager: any): void {
        this.storeManager = manager;
    }

    /** 取得初始資料並同步各 Store */
    async gameInitial(): Promise<void> {
        try {
            this.currency = this.resolveCurrency();
            console.log('HttpClientStore.gameInitial currency:', this.currency);

            await this.fetchInitialGameData();

            const gameStore = this.storeManager.getGameStore();
            const { toLegacySlotInitData } = await import('../net/SlotResponseAdapter');
            this.data = toLegacySlotInitData(this.mockMode ? gameStore.gameInfoData : null, gameStore.gameStateData, gameStore.slotLayout);
            console.log('HttpClientStore.gameInitial info:', Logger.fmt(gameStore.gameInfoData));
            console.log('HttpClientStore.gameInitial state:', Logger.fmt(gameStore.gameStateData));

            this.currency = this.data.game.currency || this.currency;
            this.setAuthKey(this.data.game.auth_key);

            gameStore.setInitExtra(this.data.machine_info.extra);
            gameStore.setGameInitData(this.data);

            const userStore = this.storeManager.getUserStore();
            userStore.setBalance(Number(this.data.game.balance) || 0);

            const templateStore = this.storeManager.getModel('TemplateStore');
            const machineInfo = this.data.machine_info;
            templateStore.setBetLeavel(machineInfo.bet_level);

            // last_bet 存在才用
            const lastBet = Number(machineInfo.last_bet);
            const betLevels = machineInfo.bet_level.map((bet: number) => Number(bet));
            const defaultBet = betLevels.includes(lastBet) ? lastBet : (betLevels[0] ?? 0);
            templateStore.setBetBalance(defaultBet);
            const index = betLevels.findIndex((bet: number) => bet === defaultBet);
            templateStore.setBetIndex(index >= 0 ? index : 0);
        } catch (error) {
            this.handleError(error);
        }
    }

    /** 建立盤面設定 */
    async gameConfig(): Promise<void> {
        try {
            const { toLegacySlotConfigData } = await import('../net/SlotResponseAdapter');
            if (!this.mockMode) {
                const gameStore = this.storeManager.getGameStore();
                gameStore.setConfigData(toLegacySlotConfigData(null, gameStore.slotLayout));
                return;
            }
            const gameStore = this.storeManager.getGameStore();
            if (!gameStore.gameInfoData) {
                await (await this.getClient()).getGameInfo(GameConfigManager.launchContext.gameCode, this.currency);
            }
        } catch (error) {
            this.handleError(error);
        }
    }

    /** 發送 Spin對應 Handler 寫入 GameStore */
    async spin(bet: number | string, buyFeatureType?: unknown): Promise<SlotApiSpinResponse | null> {
        try {
            const spin = await (await this.getClient()).spin(GameConfigManager.launchContext.gameCode, String(bet), !!buyFeatureType);
            return spin;
        } catch (error) {
            this.handleError(error);
            return null;
        }
    }

    /** 取得歷史列表 對應 Handler 寫入 Store */
    async getHistory(): Promise<any> {
        if (!this.isUpdate) {
            return this.storeManager.getGameStore().historyData;
        }

        try {
            await (await this.getClient()).getBetHistory(GameConfigManager.launchContext.gameCode, 20);
            return this.storeManager.getGameStore().historyData;
        } catch (error) {
            this.handleError(error);
            return null;
        }
    }
    /** 訂閱 Jackpot */
    async subscribeJackpotPool(): Promise<void> {
        try {
            await (await this.getClient()).subscribeJackpotPool(GameConfigManager.launchContext.gameCode);
        } catch (error) {
            this.handleError(error);
        }
    }

    /** 取消訂閱 Jackpot */
    async unsubscribeJackpotPool(): Promise<void> {
        try {
            await (await this.getClient()).unsubscribeJackpotPool(GameConfigManager.launchContext.gameCode);
        } catch (error) {
            this.handleError(error);
        }
    }

    /** 有序關閉 先取消訂閱再關 WebSocket */
    async shutdown(): Promise<void> {
        try {
            if (this.slotApiClient) {
                await this.unsubscribeJackpotPool();
            }
        } catch {
            // 取消訂閱失敗不阻擋關閉
        }
        this.close();
    }

    /** 關閉 WS heartbeat 與自動重連 */
    close(): void {
        this.slotApiClient?.close();
        this.slotApiClient = null;
        this.slotApiLoginPromise = null;
    }

    /** 取得單筆歷史明細 使用記憶體快取 */
    async getHistoryDetail(roundId: string): Promise<BetHistoryDetail | null> {
        const cachedDetail = this.getCachedBetDetail(roundId);
        if (cachedDetail) return cachedDetail;

        try {
            await (await this.getClient()).getBetDetail(roundId);
            return this.getCachedBetDetail(roundId) ?? null;
        } catch (error) {
            this.handleError(error);
            return null;
        }
    }

    /** 取得歷史明細 */
    private getCachedBetDetail(roundId: string): BetHistoryDetail | undefined {
        return this.cache.betDetails.get(roundId);
    }

    // 請求本身失敗都統一走 fallbackToMock 判斷切 mock 不能切就走原本的 handleError
    private async fetchInitialGameData(): Promise<void> {
        const { gameCode } = GameConfigManager.launchContext;
        try {
            const client = await this.getClient();
            if (this.mockMode) await client.getGameInfo(gameCode, this.currency);
            await client.getGameState(gameCode, '');
        } catch (error) {
            // fallbackToMock() 不能切就直接 throw
            const client = await this.fallbackToMock(error);
            await client.getGameInfo(gameCode, this.currency);
            await client.getGameState(gameCode, '');
        }
    }

    /** 建立連線共用 Client 含mock */
    private async getClient(): Promise<SlotApiClient> {
        if (!this.slotApiClient) {
            const options = this.mockMode ? { httpBaseUrl: '', wsUrl: this.resolveWebSocketUrl() ?? undefined } : getSlotApiConnection();
            this.slotApiClient = this.createSlotApiClient(options);
        }

        if (!this.slotApiLoginPromise) {
            const connection = this.mockMode ? this.slotApiClient.connect('') : this.runSlotApiLoginFlow(this.slotApiClient);
            this.slotApiLoginPromise = connection.catch((error) => {
                this.slotApiLoginPromise = null;
                throw error;
            });
        }

        try {
            await this.slotApiLoginPromise;
            return this.slotApiClient;
        } catch (error) {
            return this.fallbackToMock(error);
        }
    }

    /** 註冊所有 response 處理 */
    private createSlotApiClient(options: ConstructorParameters<typeof SlotApiClient>[0]): SlotApiClient {
        const client = new SlotApiClient(options);
        const gameStore = this.storeManager.getGameStore();
        client.registerHandler(new SlotSpinResponseHandler(gameStore, this));
        client.registerHandler(new GetGameInfoResponseHandler(gameStore));
        client.registerHandler(new GetGameStateResponseHandler(gameStore));
        client.registerHandler(new GetBetHistoryResponseHandler(gameStore, this));
        client.registerHandler(new GetBetDetailResponseHandler(this.cache.betDetails, gameStore));
        client.registerHandler(new JackpotPoolResponseHandler(SLOT_API_RESPONSE_TYPE.GET_JACKPOT_POOL_RESPONSE, gameStore));
        client.registerHandler(new JackpotPoolResponseHandler(SLOT_API_RESPONSE_TYPE.SUBSCRIBE_JACKPOT_POOL_RESPONSE, gameStore));
        client.registerHandler(new JackpotPoolResponseHandler(SLOT_API_RESPONSE_TYPE.JACKPOT_POOL_UPDATE, gameStore));
        return client;
    }

    /**
     * 測試流程
     * 註冊 登入 入金 連線
     * */
    private async runSlotApiLoginFlow(client: SlotApiClient): Promise<void> {
        let account = this.loadStoredAccount();
        if (!account) {
            const credentials = this.createTestCredentials();
            // await client.register(credentials);
            account = { account: credentials.account, initialDepositCompleted: false };
            this.saveStoredAccount(account);
        }

        await client.login({
            account: account.account,
            password: TEST_ACCOUNT_PASSWORD,
        });

        const wallet = await client.getWalletBalance();
        if (!account.initialDepositCompleted) {
            if (Number(wallet.balance) !== 0) {
                account.initialDepositCompleted = true;
                this.saveStoredAccount(account);
            } else {
                await client.deposit(INITIAL_DEPOSIT_AMOUNT);
                account.initialDepositCompleted = true;
                this.saveStoredAccount(account);
            }
        }

        await client.connect();
    }

    /** 測試帳號 */
    private createTestCredentials(): AccountCredentials {
        const index = 1 + Math.floor(Math.random() * 5);
        return {
            account: `ft_test0${index}`,
            password: TEST_ACCOUNT_PASSWORD,
        };
    }

    /** 本機的測試帳號 */
    private loadStoredAccount(): StoredAccount | null {
        try {
            const value = sys.localStorage.getItem(ACCOUNT_STORAGE_KEY);
            if (!value) return null;
            const stored = JSON.parse(value) as StoredAccount & Record<string, unknown>;
            if (!stored.account) return null;
            const account: StoredAccount = {
                account: stored.account,
                initialDepositCompleted: stored.initialDepositCompleted === true,
            };
            if ('password' in stored || 'token' in stored || 'depositClientRef' in stored) {
                this.saveStoredAccount(account);
            }
            return account;
        } catch {
            return null;
        }
    }

    /** 保存測試帳號 入金狀態 */
    private saveStoredAccount(account: StoredAccount): void {
        const stored: StoredAccount = {
            account: account.account,
            initialDepositCompleted: account.initialDepositCompleted,
        };
        sys.localStorage.setItem(ACCOUNT_STORAGE_KEY, JSON.stringify(stored));
    }

    /** 取得幣別 */
    private resolveCurrency(): string {
        if (typeof globalThis.location === 'undefined') return this.currency;
        // 原生的 URL 建構子在部分裝置上無法正確解析 location.href 會丟例外 讀不到網址列參數就當作沒有覆寫
        try {
            const params = new URL(globalThis.location.href).searchParams;
            return params.get('currency') ?? this.currency;
        } catch {
            return this.currency;
        }
    }

    /** 覆寫ws url */
    private resolveWebSocketUrl(): string | null {
        if (typeof globalThis.location === 'undefined') return null;
        try {
            const params = new URL(globalThis.location.href).searchParams;
            return params.get('ws_url') ?? params.get('wsUrl');
        } catch {
            return null;
        }
    }

    /** 處理錯誤 恢復狀態 */
    private handleError(error: any): void {
        console.error('[HttpClientStore] handleError stack:', Logger.fmt(error?.stack ?? error));
        const code = error?.body?.code ?? error?.code ?? 'Error';
        const message = error?.body?.message ?? error?.errors?.[0] ?? error?.message ?? String(error);
        this.storeManager.getViewStore().showAlertView(String(code), String(message));
        this.storeManager.getGameStore()?.setSpinStatus?.(GAMESTOREMAP.NEW_GAME);
    }

    /** 連線失敗時自動切換 mock
     *  僅限測試/開發 正式環境忽略
     * */
    private async fallbackToMock(error: unknown): Promise<SlotApiClient> {
        if (this.mockTriggered || this.mockMode || !autoFallbackToMock()) {
            throw error;
        }
        console.warn('[HttpClientStore] 連線失敗自動切換 mock', Logger.fmt(error));
        this.mockTriggered = true;
        this.mockMode = true;

        // 清除
        this.slotApiClient = null;
        this.slotApiLoginPromise = null;

        await startGameMock();
        return this.getClient();
    }
}
